PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?uri ?name ?length
WHERE {
  ?uri a dbo:River ;
       dbo:country dbr:China ;
       dbo:length ?length ;
       dbo:name ?name .
}
ORDER BY DESC(?length)
LIMIT 1
```

